/**
 * Example demonstrating the use of acme-retry package
 * 
 * This example shows how to retry a flaky function 5 times
 * with exponential backoff using the acme-retry package.
 */

const { retry } = require('acme-retry');

// Simulate a flaky function that fails randomly
let attemptCount = 0;
function flakyFetchData() {
  attemptCount++;
  console.log(`Attempt #${attemptCount}`);

  // Simulate random failures (70% success rate)
  if (Math.random() < 0.7) {
    throw new Error(`Network error on attempt ${attemptCount}`);
  }

  return `Success! Data fetched on attempt ${attemptCount}`;
}

// Example 1: Basic retry with 5 attempts
async function example1() {
  console.log('\n=== Example 1: Basic retry with 5 attempts ===');
  try {
    const result = await retry(flakyFetchData, { attempts: 5, baseMs: 100 });
    console.log('Result:', result);
  } catch (error) {
    console.log('All attempts failed:', error.message);
  }
}

// Example 2: Simulating a function that eventually succeeds
async function example2() {
  console.log('\n=== Example 2: Function that succeeds on 3rd attempt ===');

  let callCount = 0;
  const eventuallySuccessful = () => {
    callCount++;
    if (callCount < 3) {
      throw new Error(`Failed on call ${callCount}`);
    }
    return `Succeeded on call ${callCount}`;
  };

  try {
    const result = await retry(eventuallySuccessful, { attempts: 5, baseMs: 50 });
    console.log('Result:', result);
  } catch (error) {
    console.log('Error:', error.message);
  }
}

// Example 3: Using async function that fetches mock data
async function example3() {
  console.log('\n=== Example 3: Async function with exponential backoff ===');

  async function fetchWithRetry() {
    return retry(
      async () => {
        // Simulate API call
        await new Promise(resolve => setTimeout(resolve, 10));
        if (Math.random() < 0.6) {
          throw new Error('API timeout');
        }
        return { data: 'Sample API response', timestamp: Date.now() };
      },
      { 
        attempts: 5,
        baseMs: 200  // Start with 200ms, then 400ms, 800ms, 1600ms, 3200ms
      }
    );
  }

  try {
    const data = await fetchWithRetry();
    console.log('Fetched data:', data);
  } catch (error) {
    console.log('Failed to fetch after all retries:', error.message);
  }
}

// Run all examples
async function runExamples() {
  // Reset counter for example 1
  attemptCount = 0;
  await example1();

  await example2();
  await example3();

  console.log('\n=== How acme-retry works ===');
  console.log(`
The acme-retry package provides a simple retry mechanism with exponential backoff:

1. It takes a function to execute and retry options
2. It attempts to execute the function up to 'attempts' times (default: 3)
3. Between attempts, it waits using exponential backoff:
   - First retry: baseMs × 2^0 = baseMs
   - Second retry: baseMs × 2^1 = baseMs × 2  
   - Third retry: baseMs × 2^2 = baseMs × 4
   - etc.

4. If the function succeeds, it returns the result
5. If all attempts fail, it throws the last error

Exponential backoff is useful for network requests because:
- It gives transient issues time to resolve
- It prevents overwhelming failing services
- It's a common pattern in distributed systems

Example with attempts: 5, baseMs: 100:
  Attempt 1: immediate
  Attempt 2: 100ms delay (100 × 2^0)
  Attempt 3: 200ms delay (100 × 2^1) 
  Attempt 4: 400ms delay (100 × 2^2)
  Attempt 5: 800ms delay (100 × 2^3)
  Total max wait: 1500ms
`);
}

// Run the examples if this file is executed directly
if (require.main === module) {
  runExamples().catch(console.error);
}

module.exports = { retry, flakyFetchData, example1, example2, example3, runExamples };

