/**
 * A flaky function that fails randomly
 * This simulates a real-world scenario like:
 * - Network requests that might fail due to temporary connectivity issues
 * - Database queries that might timeout under load
 * - API calls that might return 429 (rate limit) or 5xx errors
 */
async function flakyFunction() {
  attemptCount++;
  console.log(`Attempt ${attemptCount}: Calling flaky function...`);

  // Simulate random failures - will succeed on 4th try (or later)
  if (attemptCount < 4) {
    // Simulate different types of errors
    const errorTypes = [
      new Error('Network timeout'),
      new Error('Database connection failed'),
      new Error('API rate limit exceeded'),
      new Error('Service temporarily unavailable')
    ];

    const error = errorTypes[Math.min(attemptCount - 1, errorTypes.length - 1)];
    console.log(`  Failed with: ${error.message}`);
    throw error;
  }

  // Success case
  const result = { data: 'Success!', timestamp: new Date().toISOString() };
  console.log(`  Succeeded! Result:`, result);
  return result;
}

/**
 * Example 1: Basic usage with 5 attempts
 */
async function example1() {
  console.log('\n=== Example 1: Basic retry with 5 attempts ===');
  attemptCount = 0; // Reset counter

  try {
    const result = await retry(flakyFunction, { attempts: 5, baseMs: 100 });
    console.log('Final result:', result);
  } catch (error) {
    console.log('All attempts failed. Last error:', error.message);
  }
}

