/**
 * Example usage of acme-retry package
 * Demonstrates retrying a flaky function 5 times with exponential backoff
 */

const { retry } = require('acme-retry');

// A flaky function that simulates intermittent failures
let callCount = 0;
const flakyFunction = async () => {
  callCount++;

  // Simulate different scenarios:
  // - Succeeds on 4th attempt
  // - Fails on attempts 1-3 and 5+
  if (callCount === 4) {
    console.log(`✓ Attempt ${callCount}: Function succeeded!`);
    return `Success on attempt ${callCount}!`;
  } else {
    console.log(`✗ Attempt ${callCount}: Function failed (simulated error)`);
    throw new Error(`Simulated failure on attempt ${callCount}`);
  }
};

// Example 1: Retry the flaky function 5 times with default base delay (100ms)
async function example1() {
  console.log('\n=== Example 1: Retrying 5 times with exponential backoff ===');
  callCount = 0; // Reset counter

  try {
    const result = await retry(flakyFunction, { attempts: 5, baseMs: 100 });
    console.log(`Final result: ${result}`);
  } catch (error) {
    console.log(`All attempts failed: ${error.message}`);
  }
}

// Example 2: Custom delay settings
async function example2() {
  console.log('\n=== Example 2: Custom retry settings (200ms base delay) ===');

  let customCallCount = 0;
  const customFlakyFunction = async () => {
    customCallCount++;

    // This version succeeds on 3rd attempt
    if (customCallCount === 3) {
      console.log(`✓ Custom attempt ${customCallCount}: Succeeded`);
      return `Custom success on attempt ${customCallCount}`;
    }

    console.log(`✗ Custom attempt ${customCallCount}: Failed`);
    throw new Error(`Custom failure on attempt ${customCallCount}`);
  };

  try {
    const result = await retry(customFlakyFunction, { 
      attempts: 5, 
      baseMs: 200 // Longer base delay
    });
    console.log(`Custom result: ${result}`);
  } catch (error) {
    console.log(`All custom attempts failed: ${error.message}`);
  }
}

// Example 3: Always failing function
async function example3() {
  console.log('\n=== Example 3: Function that always fails (testing max attempts) ===');

  const alwaysFails = async () => {
    throw new Error('This function always fails');
  };

  try {
    // Using default 3 attempts
    const result = await retry(alwaysFails);
    console.log(`Unexpected success: ${result}`);
  } catch (error) {
    console.log(`Expected failure after max attempts: ${error.message}`);
  }
}

// Run all examples
async function runAllExamples() {
  console.log('========== ACME-RETRY PACKAGE DEMONSTRATION ==========\n');

  await example1();
  await example2();
  await example3();

  console.log('\n========== HOW ACME-RETRY WORKS ==========');
  console.log(`
The acme-retry package provides a simple exponential backoff retry mechanism:

1. Function Signature: retry(fn, opts)
   - fn: The async function to retry
   - opts: Configuration object with:
     • attempts: Number of retry attempts (default: 3)
     • baseMs: Base delay in milliseconds (default: 100)

2. Exponential Backoff Formula:
   Delay = baseMs * (2 ^ attempt_number)

   Example with baseMs=100:
   • Attempt 1: Immediate (no delay before first try)
   • Attempt 2: 100ms delay (100 * 2^0 = 100)
   • Attempt 3: 200ms delay (100 * 2^1 = 200)  
   • Attempt 4: 400ms delay (100 * 2^2 = 400)
   • Attempt 5: 800ms delay (100 * 2^3 = 800)

3. Key Features:
   - Returns a Promise that resolves when fn succeeds
   - Throws the last error if all attempts fail
   - Simple, zero-dependency implementation
   - Exponential backoff prevents overwhelming failing services

4. Benefits:
   - Automatically retries transient failures
   - Increasing delays give systems time to recover
   - Simple API with sensible defaults
   - Works with any async function

5. When to use:
   - Network calls that might timeout
   - Database operations with occasional deadlocks
   - External API calls with rate limits
   - Any operation that might fail temporarily due to load
  `);
}

// Run the demonstration
runAllExamples().catch(console.error);

