const flakyApiCall = async () => {
  attempt++;

  // Fail the first 3 times, succeed on the 4th
  if (attempt < 4) {
    console.log(`Attempt ${attempt}: API call failed`);
    throw new Error(`API call failed on attempt ${attempt}`);
  }

  console.log(`Attempt ${attempt}: API call succeeded!`);
  return `Data from attempt ${attempt}`;
};

// Main execution
async function main() {
  console.log('Calling flaky API with retry mechanism (5 attempts)...\n');
  attempt = 0; // Reset counter

  try {
    // Retry up to 5 times with exponential backoff starting at 100ms
    const result = await retry(flakyApiCall, { attempts: 5, baseMs: 100 });
    console.log(`\n✅ Success: ${result}`);
  } catch (error) {
    console.log(`\n❌ All 5 attempts failed: ${error.message}`);
  }

  console.log(`
How it works:
1. The retry() function takes an async function and retry options
2. It retries the function up to the specified number of attempts (5 in this case)
3. Exponential backoff: waits between attempts with increasing delay
   - After 1st failure: 100ms (100 * 2^0)
   - After 2nd failure: 200ms (100 * 2^1)
   - After 3rd failure: 400ms (100 * 2^2)
   - After 4th failure: 800ms (100 * 2^3)
4. Returns the successful result or throws the last error if all attempts fail
`);
}

